import shutil
import subprocess
from pathlib import Path
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("listing-media")

INBOX_ROOT = Path("/srv/realestate/uploads/inbox")
MEDIA_ROOT = Path("/srv/realestate/media/listings")
PHOTO_EXTENSIONS = {".jpg", ".jpeg", ".png", ".heic"}


def _move_photos(source: Path, destination: Path) -> list[str]:
    destination.mkdir(parents=True, exist_ok=True)
    moved = []
    for photo in sorted(source.iterdir()):
        if photo.suffix.lower() in PHOTO_EXTENSIONS:
            shutil.move(str(photo), str(destination / photo.name))
            moved.append(photo.name)
    return moved


@mcp.tool()
def ingest_listing_photos(listing_id: str) -> dict:
    inbox_dir = INBOX_ROOT / listing_id
    if not inbox_dir.is_dir():
        return {"error": f"No uploads found for listing {listing_id}"}
    media_dir = MEDIA_ROOT / listing_id / "photos"
    moved = _move_photos(inbox_dir, media_dir)
    result = subprocess.run(
        ["photo-lint", "--min-width", "1024", "--report", "json", str(media_dir)],
        capture_output=True,
        text=True,
        timeout=300,
    )
    return {
        "moved": moved,
        "lint_exit_code": result.returncode,
        "lint_report": result.stdout.strip() or result.stderr.strip(),
    }
